public static void main(String[] args) {
    Scanner scan = new Scanner(System.in);
    int n = scan.nextInt();
    int t = scan.nextInt();
    int[] numbers = new int[t];
    for (int i = 0; i < t; i++) {
        numbers[i] = scan.nextInt();
    }

    scan.close();

    int[] cols = new int[n];
    int[] rows = new int[n];
    int[] diag = new int[2];
    for (int i = 0; i < t; i++) {
        int num = numbers[i] - 1;
        int row = num / n;
        int col = num % n;
        cols[col]++;
        rows[row]++;
        if (row == col) {
            diag[0]++;
        }
        if (row + col == n - 1) {
            diag[1]++;
        }

        if (cols[col] == n || rows[row] == n || diag[0] == n || diag[1] == n) {
            System.out.println(i + 1);
            return;
        }
    }
    System.out.println(-1);
}
